import React, { useState, useEffect } from "react";
import {
  Box,
  Typography,
  TextField,
  Button,
  Card,
  CardContent,
  IconButton,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Chip,
  Avatar,
  Menu,
  MenuItem,
  InputAdornment,
  Divider,
  useTheme,
  useMediaQuery,
  CircularProgress,
} from "@mui/material";
import {
  Search as SearchIcon,
  FilterList as FilterIcon,
  Close as CloseIcon,
  Circle as CircleIcon,
  Mail as MailIcon,
  MailOutline as MailOutlineIcon,
  Delete as DeleteIcon,
  Refresh as RefreshIcon,
} from "@mui/icons-material";
import axios from "axios";
import Swal from "sweetalert2";
import { useNavigate } from "react-router-dom"; // Import useNavigate
import { apiRequest } from "../utils/apiRequest";
import { API } from "../api/endpoints";

const NotificationPage = () => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("md"));
  const navigate = useNavigate(); // Initialize navigate

  const [notifications, setNotifications] = useState([]);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [searchTerm, setSearchTerm] = useState("");
  const [filterAnchorEl, setFilterAnchorEl] = useState(null);
  const [readFilter, setReadFilter] = useState("all");
  const [selectedNotification, setSelectedNotification] = useState(null);
  const [previewOpen, setPreviewOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const token =
    typeof window !== "undefined" ? localStorage.getItem("token") : null;

  const Toast = Swal.mixin({
    toast: true,
    position: "top-end",
    showConfirmButton: false,
    timer: 1500,
    timerProgressBar: true,
    didOpen: (toast) => {
      toast.addEventListener("mouseenter", Swal.stopTimer);
      toast.addEventListener("mouseleave", Swal.resumeTimer);
    },
    customClass: {
      container: "swal-toast-container",
      popup: "swal-toast-popup",
    },
  });
  const styleSheet = document.createElement("style");
  styleSheet.textContent = `
    .swal-toast-container {
      z-index: 9999 !important;
    }
    .swal-toast-popup {
      font-family: 'Inter', sans-serif;
      font-size: 14px;
    }
  `;
  document.head.appendChild(styleSheet);

  useEffect(() => {
    fetchNotifications();
  }, [currentPage, token]);

  const fetchNotifications = async () => {
    if (!token) {
      setError("Authentication token is missing");

      Toast.fire({
        icon: "error",
        title: "Authentication token is missing",
      });

      return;
    }

    setLoading(true);

    try {
      const response = await apiRequest({
        ...API.myNotifications,
        params: {
          paginate: true,
          page: currentPage,
        },
      });

      if (response?.success) {
        const formattedNotifications =
          response?.data?.data?.map((item) => ({
            id: item.id,
            title: item.title,
            message: item.message,
            category: item.trigger_event,
            status: item.status === "unread" ? "Open" : "Read",

            created: new Date(item.created_at).toLocaleString("en-US", {
              day: "numeric",
              month: "long",
              year: "numeric",
              hour: "numeric",
              hour12: true,
            }),

            time: item.time_ago,

            type: item.status === "unread" ? "warning" : "success",

            read: item.status === "read",

            ticket_id: item.ticket_id || item.id,
          })) || [];

        setNotifications(formattedNotifications);

        setTotalPages(response?.data?.last_page || 1);

        setError(null);
      } else {
        setError("Failed to fetch notifications");

        Toast.fire({
          icon: "error",
          title: "Failed to fetch notifications",
        });
      }
    } catch (error) {
      setError("Error fetching notifications");

      Toast.fire({
        icon: "error",
        title: error?.message || "Error fetching notifications",
      });
    } finally {
      setLoading(false);
    }
  };

  // const getRelativeTime = (createdAt) => {
  //   const now = new Date();
  //   const created = new Date(createdAt);
  //   const diffMs = now - created;
  //   const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
  //   return diffHours < 24
  //     ? `${diffHours} hours ago`
  //     : `${Math.floor(diffHours / 24)} days ago`;
  // };

  const handleUpdateStatus = async (notificationId, currentStatus) => {
    const newStatus = "read";

    try {
      const data = new FormData();

      data.append("status", newStatus);

      const response = await apiRequest({
        ...API.updateNotification(notificationId),
        method: "POST",
        data,
      });

      if (response?.success) {
        fetchNotifications();
      } else {
        Toast.fire({
          icon: "error",
          title: "Failed to update status",
        });
      }
    } catch (error) {
      Toast.fire({
        icon: "error",
        title: error?.message || "Error updating status",
      });
    }
  };

  const getNotificationColor = (type) => {
    switch (type) {
      case "success":
        return "#4caf50";
      case "error":
        return "#f44336";
      case "warning":
        return "#ff9800";
      default:
        return "#2196f3";
    }
  };

  const getNotificationIcon = (type) => {
    const color = getNotificationColor(type);
    return <CircleIcon sx={{ color, fontSize: 12 }} />;
  };

  const filteredNotifications = notifications.filter((notification) => {
    const matchesSearch =
      notification.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      notification.message.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesReadFilter =
      readFilter === "all" ||
      (readFilter === "read" && notification.read) ||
      (readFilter === "unread" && !notification.read);

    return matchesSearch && matchesReadFilter;
  });

  const handleNotificationClick = (notification) => {
    setSelectedNotification(notification);
    setPreviewOpen(true);
    if (!notification.read) {
      handleUpdateStatus(notification.id, notification.status);
    }
  };

  const handleMarkAllRead = () => {
    const unreadNotifications = notifications.filter((n) => !n.read);
    if (unreadNotifications.length > 0) {
      unreadNotifications.forEach((n) => handleUpdateStatus(n.id, n.status));
    } else {
      Toast.fire({ icon: "info", title: "No unread notifications" });
    }
  };
  const handleDeleteNotification = async (notificationId) => {
    try {
      const response = await apiRequest({
        ...API.deleteNotification(notificationId),
      });

      if (response?.success) {
        Toast.fire({
          icon: "success",
          title: "Notification deleted successfully",
        });

        fetchNotifications();
      } else {
        Toast.fire({
          icon: "error",
          title: "Failed to delete notification",
        });
      }
    } catch (error) {
      Toast.fire({
        icon: "error",
        title: error?.message || "Error deleting notification",
      });
    }
  };

  // const fetchTicketDetails = async (id) => {
  //   try {
  //     const response = await axios.get(
  //       `https://support.mcdonalds.mu/api/ticket/details/${id}`,
  //       {
  //         headers: { Authorization: `Bearer ${token}` },
  //       }
  //     );
  //     const ticketData = response.data.data;
  //     // Navigate to tickets page without id
  //     navigate("/dashboard/tickets"); // Updated to navigate without id
  //   } catch (error) {
  //     console.error(error);
  //     Toast.fire({ icon: "error", title: "Failed to fetch ticket details." });
  //   }
  // };

  const unreadCount = notifications.filter((n) => !n.read).length;

  return (
    <Box>
      <Box
        sx={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          mb: 3,
          flexDirection: { xs: "column", sm: "row" },
          gap: 2,
        }}
      >
        <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
          <RefreshIcon sx={{ color: "#666" }} />
          <Typography variant="h5" sx={{ fontWeight: 600, color: "#333" }}>
            Notifications
          </Typography>
          {unreadCount > 0 && (
            <Chip
              label={unreadCount}
              size="small"
              sx={{
                backgroundColor: "#f44336",
                color: "white",
                minWidth: 24,
                height: 20,
              }}
            />
          )}
        </Box>
        <Button
          variant="outlined"
          size="small"
          onClick={handleMarkAllRead}
          sx={{ textTransform: "none", borderColor: "#ddd", color: "#666" }}
        >
          Read All Unread
        </Button>
      </Box>

      <Box
        sx={{
          display: "flex",
          gap: 2,
          mb: 3,
          flexDirection: { xs: "column", sm: "row" },
        }}
      >
        <TextField
          placeholder="Search in projects..."
          variant="outlined"
          size="small"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          sx={{
            flexGrow: 1,
            "& .MuiOutlinedInput-root": { backgroundColor: "white" },
          }}
          InputProps={{
            startAdornment: (
              <InputAdornment position="start">
                <SearchIcon sx={{ color: "#999" }} />
              </InputAdornment>
            ),
          }}
        />
        <Button
          variant="outlined"
          startIcon={<FilterIcon />}
          onClick={(e) => setFilterAnchorEl(e.currentTarget)}
          sx={{
            textTransform: "none",
            whiteSpace: "nowrap",
            borderColor: "#ddd",
            color: "#666",
          }}
        >
          Filter
        </Button>
        <Menu
          anchorEl={filterAnchorEl}
          open={Boolean(filterAnchorEl)}
          onClose={() => setFilterAnchorEl(null)}
        >
          <MenuItem
            onClick={() => {
              setReadFilter("all");
              setFilterAnchorEl(null);
            }}
            selected={readFilter === "all"}
          >
            All Notifications
          </MenuItem>
          <MenuItem
            onClick={() => {
              setReadFilter("unread");
              setFilterAnchorEl(null);
            }}
            selected={readFilter === "unread"}
          >
            Unread Only
          </MenuItem>
          <MenuItem
            onClick={() => {
              setReadFilter("read");
              setFilterAnchorEl(null);
            }}
            selected={readFilter === "read"}
          >
            Read Only
          </MenuItem>
        </Menu>
      </Box>

      <Box sx={{ display: "flex", flexDirection: "column", gap: 2 }}>
        {loading ? (
          <Box sx={{ textAlign: "center", py: 4 }}>
            <CircularProgress />
          </Box>
        ) : filteredNotifications.length === 0 ? (
          <Box sx={{ textAlign: "center", py: 8, color: "#666" }}>
            <Typography variant="h6" sx={{ mb: 1 }}>
              No notifications found
            </Typography>
            <Typography variant="body2">
              {searchTerm
                ? "Try adjusting your search terms"
                : "You have no notifications"}
            </Typography>
          </Box>
        ) : (
          filteredNotifications.map((notification) => (
            <Card
              key={notification.id}
              sx={{
                cursor: "pointer",
                transition: "all 0.2s",
                border: "1px solid #e0e0e0",
                "&:hover": { boxShadow: 3, transform: "translateY(-1px)" },
                backgroundColor: notification.read ? "#fafafa" : "#fff9e6", // Read: light gray, Unread: light yellow
                position: "relative",
              }}
              onClick={() => handleNotificationClick(notification)}
            >
              <CardContent sx={{ p: 3 }}>
                <Box sx={{ display: "flex", alignItems: "flex-start", gap: 2 }}>
                  <Box sx={{ mt: 0.5 }}>
                    {getNotificationIcon(notification.type)}
                  </Box>
                  <Box sx={{ flexGrow: 1, minWidth: 0 }}>
                    <Box
                      sx={{
                        display: "flex",
                        justifyContent: "space-between",
                        alignItems: "flex-start",
                        mb: 1,
                        flexDirection: { xs: "column", sm: "row" },
                        gap: 1,
                      }}
                    >
                      <Typography
                        variant="h6"
                        sx={{
                          fontWeight: notification.read ? 400 : 600,
                          color: "#333",
                          fontSize: "1.1rem",
                        }}
                      >
                        {notification.title}
                      </Typography>
                      <Typography
                        variant="caption"
                        sx={{ color: "#666", whiteSpace: "nowrap" }}
                      >
                        {notification.time}
                      </Typography>
                    </Box>
                    <Typography
                      variant="body2"
                      sx={{
                        color: "#666",
                        mb: 2,
                        overflow: "hidden",
                        textOverflow: "ellipsis",
                        display: "-webkit-box",
                        WebkitLineClamp: 2,
                        WebkitBoxOrient: "vertical",
                        lineHeight: 1.4,
                      }}
                    >
                      {notification.message}
                    </Typography>
                  </Box>
                  <Box sx={{ display: "flex", gap: 1, ml: 1 }}>
                    <IconButton
                      size="small"
                      sx={{ color: "#666" }}
                      onClick={(e) => {
                        e.stopPropagation();
                        handleUpdateStatus(
                          notification.id,
                          notification.status,
                        );
                      }}
                    >
                      {notification.read ? <MailIcon /> : <MailOutlineIcon />}
                    </IconButton>
                    <IconButton
                      size="small"
                      sx={{ color: "#666" }}
                      onClick={(e) => {
                        e.stopPropagation();
                        handleDeleteNotification(notification.id); // Handle delete
                      }}
                    >
                      <DeleteIcon />
                    </IconButton>
                  </Box>
                </Box>
              </CardContent>
            </Card>
          ))
        )}
      </Box>

      {totalPages > 1 && (
        <Box sx={{ display: "flex", justifyContent: "center", mt: 3 }}>
          <Button
            variant="outlined"
            onClick={() => setCurrentPage((prev) => Math.max(prev - 1, 1))}
            disabled={currentPage === 1}
            sx={{
              mr: 1,
              textTransform: "none",
              borderColor: "#ddd",
              color: "#666",
            }}
          >
            Previous
          </Button>
          <Button
            variant="outlined"
            onClick={() =>
              setCurrentPage((prev) => Math.min(prev + 1, totalPages))
            }
            disabled={currentPage === totalPages}
            sx={{ textTransform: "none", borderColor: "#ddd", color: "#666" }}
          >
            Next
          </Button>
        </Box>
      )}

      <Dialog
        open={previewOpen}
        onClose={() => setPreviewOpen(false)}
        maxWidth="sm"
        fullWidth
        fullScreen={isMobile}
      >
        <DialogTitle
          sx={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            pb: 1,
          }}
        >
          <Typography variant="h6" sx={{ color: "#333" }}>
            Notifications Preview
          </Typography>
          <IconButton
            onClick={() => setPreviewOpen(false)}
            sx={{ color: "#666" }}
          >
            <CloseIcon />
          </IconButton>
        </DialogTitle>
        <Divider />
        <DialogContent sx={{ pt: 3 }}>
          {selectedNotification && (
            <Box>
              <Typography
                variant="h5"
                sx={{ fontWeight: 600, color: "#333", mb: 3 }}
              >
                {selectedNotification.title}
              </Typography>
              <Box
                sx={{ display: "flex", flexDirection: "column", gap: 2, mb: 3 }}
              >
                <Box sx={{ display: "flex", gap: 4 }}>
                  <Typography variant="body2" sx={{ color: "#666" }}>
                    <strong>Category:</strong> {selectedNotification.category}
                  </Typography>
                </Box>
                <Box sx={{ display: "flex", gap: 4 }}>
                  <Typography variant="body2" sx={{ color: "#666" }}>
                    <strong>Status:</strong> {selectedNotification.status}
                  </Typography>
                </Box>
                <Box sx={{ display: "flex", gap: 4 }}>
                  <Typography variant="body2" sx={{ color: "#666" }}>
                    <strong>Created:</strong> {selectedNotification.created}
                  </Typography>
                </Box>
              </Box>
              <Typography
                variant="body1"
                sx={{ color: "#444", lineHeight: 1.6 }}
              >
                {selectedNotification.message}
              </Typography>
              {/* <Box sx={{ mt: 3, textAlign: "right" }}>
                <Button
                  variant="contained"
                  onClick={() =>
                    fetchTicketDetails(selectedNotification.ticket_id)
                  }
                  sx={{
                    backgroundColor: "#4caf50",
                    "&:hover": { backgroundColor: "#45a049" },
                    textTransform: "none",
                    px: 4,
                  }}
                >
                  View Detail
                </Button>
              </Box> */}
            </Box>
          )}
        </DialogContent>
        <DialogActions sx={{ p: 3, pt: 2 }}>
          <Button
            variant="outlined"
            onClick={() => setPreviewOpen(false)}
            sx={{
              textTransform: "none",
              px: 4,
              borderColor: "#ddd",
              color: "#666",
            }}
          >
            Cancel
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default NotificationPage;
